import {buildMatchdayCrowd} from './matchday-crowd.js';
import {buildEntrancePlayers} from './entrance-players.js';
import {createMatchdayAudio} from './matchday-audio.js';
import {entranceSample,ENTRANCE_DURATION} from './matchday-route.js';

export function buildMatchdayExperience({scene,stadium,onBegin,onPose,onFinish,onExit,onPause,onPrepare,toast,reducedMotion=false,mobile=false}){
 const $=id=>document.getElementById(id),dialog=$('match-dialog'),panel=$('match-controls'),crowd=buildMatchdayCrowd(stadium.bowl,stadium.seatPositions,{mobile,reducedMotion}),players=buildEntrancePlayers(scene);
 let active=false,cinematic=false,paused=false,pending=false,time=0,playerSeconds=0,worldTime=0,uiClock=0,visualClock=0,redraw=false,token=0,lastCountdown=-1,roared=false,steps=0,stepDistance=0,lastPosition=null;
 const audio=createMatchdayAudio({onState:state=>{document.body.dataset.matchSound=state.state;$('match-volume').value=String(Math.round(state.volume*100));$('match-mute').setAttribute('aria-pressed',String(state.muted));$('match-mute').setAttribute('aria-label',state.state==='unavailable'?'重试加载看台声':state.muted?'开启看台声':'静音看台声');const labels={loading:'声浪加载中',unavailable:'声音未加载 · 点击重试',playing:'看台声浪',muted:'已静音',paused:'声音已暂停',off:'声音已关闭'};$('match-audio-status').textContent=labels[state.state]||'看台声浪';}});
 function renderUI(){const sample=entranceSample(time,{reducedMotion}),state=!active?'off':pending?'loading':paused?'paused':cinematic?sample.phase:'free';document.body.dataset.matchday=state;document.body.dataset.matchProgress=(time/ENTRANCE_DURATION).toFixed(3);document.body.dataset.matchCrowd=active?String(crowd.count):'0';document.body.dataset.matchAudioSeconds=audio.duration.toFixed(2);document.body.dataset.matchPlayers=active?players.positions:'';document.body.classList.toggle('match-cinematic',active&&cinematic);document.body.classList.toggle('match-free',active&&!cinematic);document.body.classList.toggle('match-paused',paused);
  $('match-status').textContent=pending?'正在准备入场体验':paused?'体验已暂停':cinematic?sample.label:'比赛日 · 自由漫游';$('match-pause').textContent=paused?'继续':'暂停';$('match-pause').setAttribute('aria-label',paused?'继续入场体验':'暂停入场体验');$('match-pause').hidden=!cinematic&&!paused;$('match-skip').textContent=cinematic?'跳过入场':'重播';$('match-skip').setAttribute('aria-label',cinematic?'跳过入场':'重新体验球员入场');$('match-cheer').hidden=cinematic;$('match-progress-fill').style.width=(time/ENTRANCE_DURATION*100)+'%';$('match-countdown').hidden=!active||!cinematic||pending||paused||!sample.countdown;$('match-countdown').textContent=String(sample.countdown||'');$('match-level').value=audio.level;
 }
 function launch(){if(active){renderUI();return;}players.prepare().catch(()=>{});dialog.showModal();}
 async function start(automatic=true){const id=++token;active=true;cinematic=automatic;paused=false;pending=true;time=0;playerSeconds=0;lastCountdown=-1;roared=false;stepDistance=0;lastPosition=null;panel.hidden=false;document.body.classList.add('match-active');crowd.setEnabled(true);players.root.visible=false;players.reset();
  // start() resumes the AudioContext in this click event before any network await.
  const sound=audio.start(),models=players.prepare().then(()=>onPrepare?.(players.root));dialog.close();onBegin?.({cinematic:automatic});const entry=entranceSample(0,{reducedMotion});if(!automatic)entry.x=-63;onPose?.(entry,{instant:true});if(!automatic)onFinish?.({manual:true});renderUI();const [soundResult,modelResult]=await Promise.allSettled([sound,models]);if(!active||id!==token)return;pending=false;if(soundResult.status==='rejected'||!soundResult.value)toast?.('声景暂未加载，可点击声音按钮重试；画面仍可继续体验。');if(modelResult.status==='rejected')toast?.('球员模型未加载，请检查网络后重新入场。');renderUI();
 }
 function finish(){if(!active)return;time=ENTRANCE_DURATION;playerSeconds=Math.max(playerSeconds,ENTRANCE_DURATION);cinematic=false;paused=false;onPose?.(entranceSample(time,{reducedMotion}),{instant:true});audio.setPaused(false);if(!roared){roared=true;audio.cheer();}onFinish?.();renderUI();}
 function setPaused(value){if(!active)return;paused=value;audio.setPaused(value);onPause?.(value);renderUI();}
 function exit(){if(!active){dialog.close();return;}token++;active=false;cinematic=false;paused=false;pending=false;audio.stop();crowd.setEnabled(false);players.root.visible=false;panel.hidden=true;$('match-countdown').hidden=true;document.body.classList.remove('match-active','match-cinematic','match-free','match-paused');onExit?.();renderUI();}
 function update(dt,position,yaw){redraw=false;if(!active)return;if(!paused){worldTime+=Math.min(dt,.25);if(!pending)playerSeconds+=Math.min(dt,.25);visualClock+=dt;if(visualClock>1/24){visualClock=0;redraw=true;}if(cinematic&&!pending){time=Math.min(ENTRANCE_DURATION,time+Math.min(dt,.25));const sample=entranceSample(time,{reducedMotion});onPose?.(sample,{dt});if(sample.countdown!==lastCountdown){lastCountdown=sample.countdown;audio.cue(sample.countdown);}if(sample.reveal>.57&&!roared){roared=true;audio.cheer();}if(sample.finished)finish();}
   crowd.update(worldTime);const p=cinematic?entranceSample(time,{reducedMotion}):null,walked=lastPosition?Math.hypot(position.x-lastPosition.x,position.z-lastPosition.z):0,moving=p?p.moving:walked>.003;
   if(walked<2&&moving)stepDistance+=walked;if(stepDistance>.79){stepDistance%=.79;audio.footstep(steps++);}lastPosition={x:position.x,z:position.z};players.update(playerSeconds,worldTime);players.root.visible=players.ready&&!pending&&stadium.root.visible&&stadium.bowl.visible&&Math.hypot(position.x,position.z)<110&&position.y<9;audio.update(position,yaw,dt);
  }
  uiClock+=dt;if(uiClock>.1){uiClock=0;renderUI();}
 }
 $('matchday-launch').onclick=launch;$('match-dialog-close').onclick=()=>dialog.close();$('match-start').onclick=()=>start(true);$('match-manual').onclick=()=>start(false);$('match-pause').onclick=()=>setPaused(!paused);$('match-skip').onclick=()=>cinematic?finish():start(true);$('match-cheer').onclick=()=>audio.cheer();$('match-exit').onclick=exit;$('match-volume').oninput=e=>audio.setVolume(Number(e.target.value)/100);$('match-mute').onclick=()=>{if(audio.state==='unavailable')audio.start().then(()=>{if(paused)audio.setPaused(true);});else audio.setMuted(!audio.muted);};
 return{launch,start,exit,finish,update,setPaused,get active(){return active;},get cinematic(){return active&&cinematic;},get paused(){return paused;},isAnimating:()=>active&&!paused&&(cinematic&&!pending||redraw&&stadium.root.visible&&stadium.bowl.visible)};
}
